  R23Visuals visuals;R24DualDefinition definition;Camera head;readonly Transform[] models=new Transform[2],spin=new Transform[2],art=new Transform[2],arrows=new Transform[2],muzzles=new Transform[2],flashAnchors=new Transform[2];readonly R23GunFeedback[] hud=new R23GunFeedback[2];readonly R23Audio[] audio=new R23Audio[2];readonly LineRenderer[] lasers=new LineRenderer[2];readonly R23ShotPose[] shotPoses=new R23ShotPose[2];readonly List<UnityEngine.Object> owned=new List<UnityEngine.Object>();readonly List<TextMesh> secrets=new List<TextMesh>();Font secretFont;Material secretMaterial;bool initialized,disposed;
  public bool Visible{get{return models[0]!=null&&models[0].gameObject.activeInHierarchy||models[1]!=null&&models[1].gameObject.activeInHierarchy;}}public bool Ready{get;private set;}public string Failure{get;private set;}public Func<Vector3,Vector3,float,Vector3> TraceAim;public Func<int,bool> AimAllowed;public string AmmoText(int side){return hud[side]==null?"":hud[side].AmmoText;}public bool PanelVisible(int side){return hud[side]!=null&&hud[side].PanelVisible;}public bool LaserVisible(int side){return lasers[side]!=null&&lasers[side].enabled;}public Transform Model(int side){return models[side];}public Transform Muzzle(int side){return muzzles[side];}public R23ShotPose FiringPose(int side){return shotPoses[side];}
  public void Initialize(string profile,Camera camera,Transform renderParent){if(initialized||renderParent==null||camera==null)throw new ArgumentException("Actual dual render host/camera required");initialized=true;definition=new R24DualDefinition(profile);head=camera;for(int side=0;side<2;side++){models[side]=Node("Actual "+profile+" independent gun "+side,renderParent);models[side].localScale=Vector3.one*definition.Scale;spin[side]=Node("OriginalUpFlickFullTurn",models[side]);spin[side].localPosition=V(R24DualDefinition.SpinPivot);art[side]=Node("Authentic source pair model",spin[side]);art[side].localPosition=-V(R24DualDefinition.SpinPivot);muzzles[side]=Node("Actual source dual muzzle",models[side]);muzzles[side].localPosition=V(definition.Muzzle);flashAnchors[side]=Node("Original five-sided flash start",models[side]);flashAnchors[side].localPosition=new Vector3(0,.045f,definition.Automatic?.465f:.3525f);hud[side]=new R23GunFeedback(transform,muzzles[side]);audio[side]=new R23Audio(models[side],muzzles[side]);arrows[side]=Arrow(art[side]);arrows[side].gameObject.SetActive(false);if(definition.Automatic)lasers[side]=Laser();}StartCoroutine(Guard(Load()));}
  IEnumerator Guard(IEnumerator work){var stack=new Stack<IEnumerator>();stack.Push(work);while(stack.Count>0){object value;try{var top=stack.Peek();if(!top.MoveNext()){stack.Pop();continue;}value=top.Current;}catch(Exception e){Failure=e.ToString();yield break;}var nested=value as IEnumerator;if(nested!=null)stack.Push(nested);else yield return value;}Ready=true;Hide();}
