  public void Present(R24DualOwner owner,R24DualFeedback first,R24DualFeedback second,R23ShotPose dominantNeutral,R23ShotPose otherNeutral,bool dominantVisible,bool otherVisible,bool enabled){if(!Ready||owner==null)return;for(int side=0;side<2;side++){var state=owner.ReadHand(side);var feedback=side==0?first:second;bool visible=enabled&&(side==0?dominantVisible:otherVisible);models[side].gameObject.SetActive(visible);if(!visible){hud[side].Hide();if(lasers[side]!=null)lasers[side].enabled=false;continue;}var neutral=side==0?dominantNeutral:otherNeutral;R23ShotPose model,shot;R23WeaponPoseMath.Resolve(neutral,definition.Muzzle,definition.Scale,feedback.Distance,feedback.Pitch,feedback.Yaw,!definition.Automatic,out model,out shot);shotPoses[side]=shot;models[side].SetPositionAndRotation(V(model.Origin),Quaternion.LookRotation(V(model.Forward),V(model.Up)));models[side].localScale=Vector3.one*definition.Scale;spin[side].localRotation=state.SpinElapsed>=.36f?Quaternion.identity:Quaternion.Euler(-360*Mathf.SmoothStep(0,1,state.SpinElapsed/.36f),0,0);arrows[side].gameObject.SetActive(false);if(state.Loaded==0)arrows[side].rotation=Quaternion.identity;
    hud[side].PresentAmmo(models[side],definition.Scale,state.Loaded,owner.Reserve,state.PhysicalHand==0,true);hud[side].PresentFlash(feedback.Flash,flashAnchors[side],.055f,.015f);Vector3 origin=V(shot.Origin),forward=V(shot.Forward),end=TraceAim==null?origin+forward*180:TraceAim(origin,forward,180);bool aiming=state.Loaded>0&&(AimAllowed==null||AimAllowed(state.PhysicalHand));if(lasers[side]!=null){lasers[side].enabled=aiming&&TraceAim!=null;if(lasers[side].enabled){lasers[side].SetPosition(0,origin);lasers[side].SetPosition(1,end);}hud[side].PresentReticle(head,end,forward,70+feedback.Bloom,false);}else hud[side].PresentReticle(head,end,forward,98+feedback.Bloom,aiming,false,false,true);hud[side].Tick(Time.unscaledTime);
   }foreach(var label in secrets)if(label!=null)label.gameObject.SetActive(Vector3.Distance(head.transform.position,label.transform.position)<.14f);}
  public bool TryReadGloveContact(R24DualOwner owner,int side,out Vector3 position,out Quaternion rotation){position=Vector3.zero;rotation=Quaternion.identity;if(!Ready||owner==null||!models[side].gameObject.activeInHierarchy)return false;var offset=definition.Automatic?new Vector3(0,0,-.0127f):new Vector3(0,.1524f-.1016f*Mathf.Cos(35*Mathf.Deg2Rad),-.1016f*Mathf.Sin(35*Mathf.Deg2Rad));position=models[side].TransformPoint(V(R24DualDefinition.SpinPivot)+offset/definition.Scale);rotation=models[side].rotation*Quaternion.Euler(definition.Automatic?0:35,0,0)*Quaternion.Inverse(R23TrackedGripPose.LocalRotation)*R23TrackedGripPose.GloveLocalRotation(owner.ReadHand(side).PhysicalHand);return true;}
  public void Play(R24DualStep step){if(step==null)return;for(int side=0;side<2;side++){var shot=side==0?step.Dominant:step.Other;string reload=side==0?step.DominantReload:step.OtherReload;if(shot!=null)audio[side].Play(definition.Id,"shot",true);if(reload=="mag_insert")audio[side].Play(definition.Id,reload,false);}}
  public void SetSfxVolume(float value){foreach(var voice in audio)if(voice!=null)voice.SetSfxVolume(value);}public void Hide(){foreach(var model in models)if(model!=null)model.gameObject.SetActive(false);foreach(var h in hud)if(h!=null)h.Hide();foreach(var laser in lasers)if(laser!=null)laser.enabled=false;foreach(var a in audio)if(a!=null)a.Stop();}
  public void PresentDock(Transform anchor){if(!Ready||anchor==null)return;for(int side=0;side<2;side++){models[side].gameObject.SetActive(true);models[side].SetPositionAndRotation(anchor.TransformPoint(new Vector3(side==0?.09f:-.09f,0,0)),anchor.rotation*Quaternion.Euler(0,(side==0?.12f:-.12f)*Mathf.Rad2Deg,0));models[side].localScale=Vector3.one*definition.Scale;spin[side].localRotation=Quaternion.identity;arrows[side].gameObject.SetActive(false);hud[side].Hide();if(lasers[side]!=null)lasers[side].enabled=false;}}
  Transform Arrow(Transform parent){var root=Node("Source occupied-hand UP flick cue",parent);root.localPosition=new Vector3(.09f,.07f,.10f);var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));owned.Add(m);m.SetColor("_BaseColor",new Color(1,.72f,.16f));m.SetFloat("_Metallic",.15f);m.SetFloat("_Smoothness",.5f);m.SetColor("_EmissionColor",new Color(1,.72f,.16f));m.EnableKeyword("_EMISSION");Box(root,new Vector3(.009f,.09f,.006f),new Vector3(0,.045f,0),0,m);for(int sign=-1;sign<=1;sign+=2)Box(root,new Vector3(.009f,.035f,.006f),new Vector3(sign*.01f,.077f,0),sign*.65f*Mathf.Rad2Deg,m);return root;}
  void Box(Transform parent,Vector3 size,Vector3 at,float angle,Material material){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name="Actual source reload arrow box";go.layer=18;go.transform.SetParent(parent,false);go.transform.localPosition=at;go.transform.localScale=size;go.transform.localRotation=Quaternion.Euler(0,0,angle);var collider=go.GetComponent<Collider>();collider.enabled=false;Destroy(collider);go.GetComponent<MeshRenderer>().sharedMaterial=material;}
