  void Secret(Transform parent){if(secretFont==null){secretFont=Resources.Load<Font>("R23GodotUI");if(secretFont==null)throw new InvalidOperationException("Actual shared source UI font absent");secretMaterial=new Material(Shader.Find("Ashfall/R23GunFeedback"));secretMaterial.SetFloat("_Font",1);secretMaterial.SetFloat("_Depth",4);secretMaterial.SetFloat("_Cull",2);secretMaterial.SetColor("_Color",new Color(222f/255,215f/255,199f/255));owned.Add(secretMaterial);Font.textureRebuilt+=FontRebuilt;}for(int sign=-1;sign<=1;sign+=2){var t=Node(sign<0?"InsideMatadorBore094_Left":"InsideMatadorBore094_Right",parent);t.localPosition=new Vector3(sign*.021f,.0694f,.367f);t.localRotation=Quaternion.Euler(0,180,0);var label=t.gameObject.AddComponent<TextMesh>();label.font=secretFont;label.fontSize=32;label.characterSize=1;label.text="Don't look\nunder here.";label.anchor=TextAnchor.MiddleCenter;label.alignment=TextAlignment.Center;label.color=Color.white;label.richText=false;t.GetComponent<MeshRenderer>().sharedMaterial=secretMaterial;secretFont.RequestCharactersInTexture(label.text,32);float height=t.GetComponent<MeshRenderer>().localBounds.size.y;if(height>0)t.localScale=Vector3.one*(64*.000065f/height);secrets.Add(label);}FontRebuilt(secretFont);}
